templates.jenkins:
pipeline {
    agent any

    environment {
        APP_ENV = "${env.APP_ENV ?: 'staging'}"
        NODE_VERSION = '20'
        PYTHON_VERSION = '3.11'
    }

    stages {
        stage('Build') {
            steps {
                script {
                    {{BUILD_STEPS}}
                }
            }
        }

        stage('Code Quality') {
            steps {
                script {
                    {{QUALITY_STEPS}}
                }
            }
        }

        stage('Test') {
            steps {
                script {
                    {{TEST_STEPS}}
                }
            }
        }

        stage('Deploy') {
            when {
                branch 'main'
            }
            steps {
                script {
                    {{AUTH_STEPS}}
                    {{DEPLOY_STEPS}}
                }
            }
        }
    }

    post {
        always {
            script {
                {{ALERT_STEPS}}
            }
        }
        failure {
            script {
                {{ROLLBACK_STEPS}}
            }
        }
    }
}

withSonarQubeEnv('SonarQubeServer') {
    sh '''
        sonar-scanner \
            -Dsonar.projectKey=${SONAR_PROJECT_KEY} \
            -Dsonar.organization=${SONAR_ORG} \
            -Dsonar.sources=. \
            -Dsonar.python.version=3.11 \
            -Dsonar.javascript.lcov.reportPaths=coverage/lcov.info
    '''
}
timeout(time: 5, unit: 'MINUTES') {
    waitForQualityGate abortPipeline: true
}

