templates.jenkins:
withKubeConfig([credentialsId: 'kubeconfig-credentials']) {
    sh '''
        export IMAGE_TAG=$(echo $GIT_COMMIT | cut -c1-7)
        export DEPLOY_TIMESTAMP=$(date +%s)
        kubectl config set-context --current --namespace=${KUBE_NAMESPACE:-default}
        echo "Deploying image tag: $IMAGE_TAG"
        for manifest in k8s/*.yaml; do
            echo "Applying manifest: $manifest"
            envsubst < "$manifest" | kubectl apply -f -
        done
        for deployment in $(kubectl get deployments -n ${KUBE_NAMESPACE:-default} -l app=${KUBE_APP_LABEL} -o name); do
            echo "Checking rollout status for: $deployment"
            kubectl rollout status $deployment -n ${KUBE_NAMESPACE:-default} --timeout=300s
        done
        kubectl get pods -n ${KUBE_NAMESPACE:-default} -l app=${KUBE_APP_LABEL} -o wide
        kubectl get services -n ${KUBE_NAMESPACE:-default} -l app=${KUBE_APP_LABEL}
    '''
}

