templates.github_actions:
- name: Send Google Chat Notification
  run: |
    STATUS="${{ needs.deploy.result == 'success' && 'SUCCESS ✅' || 'FAILED ❌' }}"
    curl -X POST -H 'Content-Type: application/json' \
      -d "{
        \"cards\": [{
          \"header\": {
            \"title\": \"Pipeline ${STATUS}\",
            \"subtitle\": \"${{ github.repository }} - ${{ github.ref_name }}\"
          },
          \"sections\": [{
            \"widgets\": [
              { \"keyValue\": { \"topLabel\": \"Repository\", \"content\": \"${{ github.repository }}\" } },
              { \"keyValue\": { \"topLabel\": \"Branch\", \"content\": \"${{ github.ref_name }}\" } },
              { \"keyValue\": { \"topLabel\": \"Commit\", \"content\": \"${{ github.sha }}\" } },
              { \"keyValue\": { \"topLabel\": \"Workflow\", \"content\": \"Run #${{ github.run_number }}\", \"onClick\": { \"openLink\": { \"url\": \"${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }}\" } } } }
            ]
          }]
        }]
      }" \
      ${{ secrets.GOOGLE_CHAT_WEBHOOK_URL }}

