templates.github_actions:
- name: Deploy to Vercel
  uses: amondnet/vercel-action@v25
  with:
    vercel-token: ${{ secrets.VERCEL_TOKEN }}
    vercel-org-id: ${{ secrets.VERCEL_ORG_ID }}
    vercel-project-id: ${{ secrets.VERCEL_PROJECT_ID }}
    vercel-args: ${{ github.ref == 'refs/heads/main' && '--prod' || '' }}
    working-directory: .
    scope: ${{ secrets.VERCEL_ORG_ID }}
- name: Verify Vercel deployment
  run: |
    DEPLOY_URL=$(curl -s -H "Authorization: Bearer ${{ secrets.VERCEL_TOKEN }}" \
      "https://api.vercel.com/v9/projects/${{ secrets.VERCEL_PROJECT_ID }}/deployments?limit=1" \
      | jq -r '.deployments[0].url')
    echo "Deployed to: https://$DEPLOY_URL"
    curl -sf -o /dev/null -w '%{http_code}' "https://$DEPLOY_URL" || echo 'Verification failed'

